select id, owner_id, title, description, due_date, importance, urgency, estimated_minutes, status, category, created_at, updated_at, case when status = 'DONE' then 0 else importance * 12 + urgency * 9 + case when due_date <= current_date - 4 then 75 when due_date <= current_date - 3 then 70 when due_date <= current_date - 2 then 65 when due_date < current_date then 60 when due_date = current_date then 36 when due_date = current_date + 1 then 28 when due_date <= current_date + 3 then 20 when due_date <= current_date + 7 then 12 when due_date <= current_date + 14 then 6 else 0 end + case when estimated_minutes >= 180 then 8 when estimated_minutes >= 90 then 4 else 0 end + case when status = 'IN_PROGRESS' then 6 else 0 end end as recommended_score from tasks where owner_id = #{ownerId}
and status = #{query.status}
and lower(category) = lower(#{query.category})
order by due_date asc, importance desc, urgency desc, updated_at desc
order by importance desc, urgency desc, due_date asc, updated_at desc
order by updated_at desc
order by recommended_score desc, due_date asc, importance desc, urgency desc, updated_at desc
limit #{query.size} offset #{query.offset}

